def fib4(n: int):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0 or n == 1 or n == 3:
        return 0
    if n == 2:
        return 2

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    for _ in range(4, n + 1):
        next_val = a + b + c + d
